const params = {};
if ($.input.status) params.status = $.input.status;
return { params };

const resp = $.steps.listInvitees.response || {};
const invitees = resp.collection || [];
return {
  invitees: invitees.map(i => ({
    uri: i.uri,
    name: i.name,
    email: i.email,
    status: i.status,
    createdAt: i.created_at,
    timezone: i.timezone,
    questionsAndAnswers: i.questions_and_answers || []
  })),
  count: invitees.length,
  eventUuid: $.input.eventUuid,
  summary: `Found ${invitees.length} invitee${invitees.length === 1 ? '' : 's'} for event ${$.input.eventUuid}`
};
